// === Tab: mySketch ===
ArrayList<Particle> particles = new ArrayList<Particle>();
let particleCount = 250;
let maxHistoryCount = 15;
let maxSize = 30;
let force = 0;
let tooltip = "".concat("Controles:\n", 
                           "- Segure o botão esquerdo do mouse para atrair.\n", 
                           "- Segure o botão direito do mouse para repelir.\n", 
                           "- Segure 'w' ou 's' para adicionar ou remover partículas.\n", 
                           "- Pressione o botão do meio do mouse para reiniciar.");


class Particle {

    pos;
    vel;
    acc;
    target;

    ArrayList<PVector> history;

    baseHue;
    variation;
    speed;
    maxSpeed;
    character;

  constructor() {
    this.pos = new PVector(width/2, height+50);
    this.vel = PVector.random2D();
    this.vel.mult(10);
    this.acc = new PVector(0, 0);
    this.target = new PVector(0, 0);
    this.history = new ArrayList<PVector>();

    this.baseHue = 200;

    this.variation = random(0.75, 1);
    this.speed = random(0.25, 0.75);
    this.maxSpeed = random(5, 10);
    this.character = randomCharacter();
  }

  randomCharacter() {
    let chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    return chars.charAt(int(random(chars.length())));
  }

  function move() {
    this.target.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
    this.target.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

    // let para o alvo.
    let steer = new PVector(this.target.x, this.target.y);
    steer.sub(this.pos);
    steer.sub(this.vel); // let com que pare.
    steer.normalize();
    steer.mult(this.speed*this.variation);
    this.acc.add(steer);

    let d = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

    // Atrair/repelir com controles do mouse.
    if (mousePressed && mouseButton != CENTER && d < 200) {
      let source = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
      let push = new PVector(this.pos.x, this.pos.y);
      push.sub(source);
      push.normalize();
      push.mult(force);

      if (mouseButton == LEFT) {
        push.mult(-1);
      }

      this.acc.add(push);
    }

    // Aplicar resistência do ar se estiver perto do alvo.
    let thresh = 100;
    if (d < thresh) {
      let airDrag = map(d, 0, thresh, 1, 0.95);
      this.vel.mult(airDrag);
    }

    // Mover.
    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);
    this.acc.mult(0);

    this.history.add(0, new PVector(this.pos.x, this.pos.y));

    if (this.history.size() > maxHistoryCount) {
      this.history.remove(maxHistoryCount);
    }
  }

  function display() {
    let hueDif = 50;

    let historySize = this.history.size();

    for (i = historySize-1; i > 0; i--) {
      let w = map(i, 0, historySize, maxSize, 0);
      let h = constrain(map(i, 0, historySize, this.baseHue, this.baseHue+hueDif), 0, 360);
      fill(h, 360, 360);
      textSize(w);
      text(this.character, this.history.get(i).x, this.history.get(i).y);
    }

    // let matiz se estiver abaixo do limite.
    if (dist(this.pos.x, this.pos.y, this.target.x, this.target.y) < 100) {
      this.baseHue += 1;
      if (this.baseHue > 360-hueDif) {
        this.baseHue = -hueDif;
      }
    }
  }
}


function setup() {
  createCanvas(window.innerWidth, window.innerHeight);

  colorMode(HSB, 360);
  textAlign(CENTER, CENTER);

  reset();

  // let alvo padrão para o centro.
  window.simulatedMouseX = width/2;
  window.simulatedMouseY = height/2;
} 


function draw() {
  background(0);

  // let a força quanto mais tempo o clique for mantido.
  if (mousePressed) {
    force += 0.1;
  }

  for (i = 0; i < particles.size(); i++) {
    particles.get(i).move();
    particles.get(i).display();
  }

  fill(255);
  textSize(18);
  text(tooltip, 20, 20);

  let settings = "".concat("Contagem: ", particles.size(), "\n", "FPS: ", frameRate.toFixed(2));
  text(settings, 20, height-40);
}


function keyPressed() {
  if (key == 'w') {
    for (i = 0; i < 10; i++) {
      particles.add(new Particle());
    }
  } else if (key == 's') {
    for (i = 0; i < 10; i++) {
      if (particles.size() == 0) {
        return;
      }

      let index = int(random(particles.size()));
      particles.remove(index);
    }
  }
}


function mousePressed() {
  force = 0;

  if (mouseButton == CENTER) {
    reset();
  }
}


function reset() {
  particles.clear();

  for (i = 0; i < particleCount; i++) {
    particles.add(new Particle());
  }
}

